package com.g4t0xx.nettunnel;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.net.VpnService;
import android.os.*;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import com.wireguard.config.Config;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.UUID;

public class MainActivity extends Activity {
    private final Handler handler=new Handler(Looper.getMainLooper());
    private LinearLayout root,list;
    private TextView status,stats,notice;
    private Button connect,add,file;
    private boolean lastActive=false;
    private JSONArray profiles=new JSONArray();
    private String selected="";
    private Profiles storage;
    private static final int BG=0xff0b090c,SURFACE=0xff1c141b,TEXT=0xfffff7fa,MUTED=0xffc9b9c2,RED=0xffbe123c,HOT=0xffff8097;
    private int dp(float value){return (int)(getResources().getDisplayMetrics().density*value+.5f);}
    private TextView text(String value,int size,int color){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(color);v.setPadding(0,dp(6),0,dp(6));return v;}
    private GradientDrawable background(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(10));d.setStroke(dp(1),0xff49333f);return d;}
    private Button button(String value,boolean primary){Button b=new Button(this);b.setText(value);b.setTextColor(TEXT);b.setAllCaps(false);b.setTextSize(15);b.setBackground(background(primary?RED:SURFACE));LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-1,dp(52));params.setMargins(0,dp(8),0,dp(4));b.setLayoutParams(params);return b;}
    @Override public void onCreate(Bundle state){super.onCreate(state);storage=new Profiles(this);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(BG);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(24),dp(20),dp(24),dp(28));scroll.addView(root);setContentView(scroll);
        scroll.setOnApplyWindowInsetsListener((view,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars());view.setPadding(bars.left,bars.top,bars.right,bars.bottom);}else{view.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());}return insets;});scroll.requestApplyInsets();
        TextView brand=text("G4T0XX / NETTUNNEL PRO",16,HOT);brand.setTypeface(null,Typeface.BOLD);root.addView(brand);TextView title=text("Sua conexão.\nSeu servidor.",34,TEXT);title.setTypeface(null,Typeface.BOLD);root.addView(title);root.addView(text("VPN WireGuard com perfis locais e estado real do túnel.",15,MUTED));
        LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(18),dp(18),dp(18),dp(18));panel.setBackground(background(SURFACE));LinearLayout.LayoutParams panelParams=new LinearLayout.LayoutParams(-1,-2);panelParams.setMargins(0,dp(24),0,dp(16));panel.setLayoutParams(panelParams);root.addView(panel);status=text("Desconectado",21,TEXT);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);panel.addView(status);stats=text("Recebido: 0 B · Enviado: 0 B",13,MUTED);panel.addView(stats);connect=button("Conectar",true);connect.setOnClickListener(v->toggle());panel.addView(connect);
        notice=text("Importe um perfil .conf do seu servidor WireGuard. Nenhum servidor ou acesso à internet é fornecido pelo aplicativo.",13,MUTED);root.addView(notice);root.addView(text("Perfis",22,TEXT));list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);root.addView(list);add=button("Adicionar configuração",true);add.setOnClickListener(v->editor(null));root.addView(add);file=button("Importar arquivo .conf",false);file.setOnClickListener(v->{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(intent,10);});root.addView(file);root.addView(text("Chaves privadas protegidas pelo Android Keystore. O aplicativo não inclui medições simuladas, anúncios ou assinaturas.",12,MUTED));
        try{profiles=storage.read();if(profiles.length()>0)selected=profiles.getJSONObject(0).getString("id");}catch(Exception e){notice.setText("Não foi possível abrir os perfis protegidos. Os dados foram preservados. Importe o perfil original novamente.");}renderProfiles();
    }
    private void renderProfiles(){list.removeAllViews();if(profiles.length()==0)list.addView(text("Nenhum perfil cadastrado.",14,MUTED));for(int i=0;i<profiles.length();i++){try{JSONObject p=profiles.getJSONObject(i);String id=p.getString("id");LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(dp(14),dp(10),dp(14),dp(10));row.setBackground(background(id.equals(selected)?0xff421426:SURFACE));LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-1,-2);params.setMargins(0,dp(8),0,dp(4));row.setLayoutParams(params);Button choose=button(p.getString("name")+(id.equals(selected)?" · Selecionado":""),false);choose.setEnabled(!TunnelService.active&&!TunnelService.busy);choose.setOnClickListener(v->{selected=id;renderProfiles();});row.addView(choose);Button remove=button("Excluir perfil",false);remove.setEnabled(!TunnelService.active&&!TunnelService.busy);remove.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Excluir "+p.optString("name")+"?").setMessage("A chave privada deste perfil será removida do aplicativo. Guarde seu arquivo original.").setNegativeButton("Cancelar",null).setPositiveButton("Excluir",(dialog,which)->{try{JSONArray next=new JSONArray();for(int index=0;index<profiles.length();index++)if(!profiles.getJSONObject(index).getString("id").equals(id))next.put(profiles.getJSONObject(index));storage.write(next);profiles=next;selected=profiles.length()>0?profiles.getJSONObject(0).getString("id"):"";renderProfiles();}catch(Exception e){notice.setText("Não foi possível excluir. O perfil foi preservado.");}}).show());row.addView(remove);list.addView(row);}catch(JSONException ignored){}}}
    private void editor(String initial){LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(20),dp(8),dp(20),dp(8));EditText name=new EditText(this);name.setHint("Nome do perfil");name.setTextColor(TEXT);name.setHintTextColor(MUTED);name.setSingleLine();name.setContentDescription("Nome do perfil");form.addView(name);EditText config=new EditText(this);config.setHint("Cole a configuração [Interface] e [Peer]");config.setTextColor(TEXT);config.setHintTextColor(MUTED);config.setMinLines(6);config.setMaxLines(10);config.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE|InputType.TYPE_TEXT_VARIATION_PASSWORD);config.setContentDescription("Configuração WireGuard");if(initial!=null)config.setText(initial);form.addView(config);CheckBox reveal=new CheckBox(this);reveal.setText("Mostrar configuração e chave privada");reveal.setTextColor(MUTED);reveal.setOnCheckedChangeListener((b,checked)->{config.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE|(checked?InputType.TYPE_TEXT_VARIATION_VISIBLE_PASSWORD:InputType.TYPE_TEXT_VARIATION_PASSWORD));config.setSelection(config.length());});form.addView(reveal);TextView error=text("",13,HOT);error.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);form.addView(error);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Adicionar perfil WireGuard").setView(form).setNegativeButton("Cancelar",null).setPositiveButton("Salvar",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{String label=name.getText().toString().trim();String raw=config.getText().toString().trim();if(label.isEmpty()||label.length()>60){name.setError("Digite um nome de até 60 caracteres");name.requestFocus();return;}if(raw.length()>65536)throw new IllegalArgumentException();Config parsed=Config.parse(new ByteArrayInputStream(raw.getBytes(StandardCharsets.UTF_8)));if(parsed.getPeers().isEmpty())throw new IllegalArgumentException();JSONObject profile=new JSONObject().put("id",UUID.randomUUID().toString()).put("name",label).put("config",raw);JSONArray next=new JSONArray(profiles.toString());next.put(profile);storage.write(next);profiles=next;selected=profile.getString("id");renderProfiles();notice.setText("Perfil salvo com criptografia. Pronto para conectar.");dialog.dismiss();}catch(Exception e){error.setText("Configuração inválida ou não foi possível salvá-la. Revise [Interface], PrivateKey, Address e [Peer].");config.requestFocus();}}));dialog.show();}
    private void toggle(){if(TunnelService.busy)return;if(TunnelService.active){startService(new Intent(this,TunnelService.class).setAction("stop"));return;}if(selected.isEmpty()){notice.setText("Adicione e selecione um perfil antes de conectar.");return;}Intent permission=VpnService.prepare(this);if(permission!=null)startActivityForResult(permission,11);else connectNow();}
    private void connectNow(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},12);startForegroundService(new Intent(this,TunnelService.class).setAction("start").putExtra("profileId",selected));}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==11){if(result==RESULT_OK)connectNow();else notice.setText("Permissão VPN recusada. Nenhuma conexão foi iniciada.");}if(request==10&&result==RESULT_OK&&data!=null&&data.getData()!=null){try(InputStream input=getContentResolver().openInputStream(data.getData())){if(input==null)throw new IOException();ByteArrayOutputStream output=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int count;while((count=input.read(buffer))!=-1){output.write(buffer,0,count);if(output.size()>65536)throw new IOException();}editor(output.toString(StandardCharsets.UTF_8.name()));}catch(Exception e){notice.setText("Não foi possível importar. Escolha um arquivo .conf de até 64 KB.");}}}
    private String bytes(long value){if(value<1024)return value+" B";if(value<1048576)return String.format(java.util.Locale.getDefault(),"%.1f KB",value/1024.);return String.format(java.util.Locale.getDefault(),"%.2f MB",value/1048576.);}
    private final Runnable update=new Runnable(){public void run(){if(lastActive!=TunnelService.active){lastActive=TunnelService.active;if(lastActive&&!TunnelService.profileId.isEmpty())selected=TunnelService.profileId;renderProfiles();}add.setEnabled(!TunnelService.active&&!TunnelService.busy);file.setEnabled(!TunnelService.active&&!TunnelService.busy);status.setText(TunnelService.status);stats.setText("Recebido: "+bytes(TunnelService.received)+" · Enviado: "+bytes(TunnelService.sent)+(TunnelService.handshake>0?"\nÚltimo handshake: "+android.text.format.DateFormat.getTimeFormat(MainActivity.this).format(new java.util.Date(TunnelService.handshake)):""));connect.setText(TunnelService.busy?"Conectando…":TunnelService.active?"Desconectar":"Conectar");connect.setEnabled(!TunnelService.busy);if(!TunnelService.error.isEmpty())notice.setText(TunnelService.error);handler.postDelayed(this,1000);}};
    @Override protected void onResume(){super.onResume();handler.post(update);}
    @Override protected void onPause(){handler.removeCallbacks(update);super.onPause();}
}
